import { useMemo, useSyncExternalStore } from 'react'
import { statusOf } from '../../data/card_ordering'
import { defaultColumnAccent, type StateConfig } from '../../data/data_types'
import {
    CARD_ADDED_EVENT,
    CARD_REMOVED_EVENT,
    cardCollectionFieldChangedEvent,
    dataService,
    type CardAddedEventDetail,
    type CardRemovedEventDetail,
    type DataService,
} from '../../services/data/data_service'

export interface VisibleCardColumn {
    color: string
    status: string
}

function areSameColumns(first: VisibleCardColumn[], second: VisibleCardColumn[]) {
    return first.length === second.length && second.every((column, index) => (
        first[index].color === column.color && first[index].status === column.status
    ))
}

class CardViewColumnStore {
    private columns: VisibleCardColumn[]
    private listener: (() => void) | null = null
    private readonly service: DataService
    private readonly states: StateConfig[]
    private readonly statusCounts: Map<string, number>

    constructor(states: StateConfig[], service: DataService) {
        this.service = service
        this.states = states
        this.statusCounts = new Map()
        const cards = service.getState().snapshot?.activeCards ?? []
        for (const card of cards) this.incrementStatus(statusOf(card))
        this.columns = this.visibleColumns()
    }

    readonly getSnapshot = () => this.columns

    readonly subscribe = (listener: () => void) => {
        this.listener = listener
        this.service.addEventListener(CARD_ADDED_EVENT, this.handleCardAdded)
        this.service.addEventListener(cardCollectionFieldChangedEvent('status'), this.handleCardStatusesChanged)
        this.service.addEventListener(CARD_REMOVED_EVENT, this.handleCardRemoved)

        return () => {
            this.listener = null
            this.service.removeEventListener(CARD_ADDED_EVENT, this.handleCardAdded)
            this.service.removeEventListener(cardCollectionFieldChangedEvent('status'), this.handleCardStatusesChanged)
            this.service.removeEventListener(CARD_REMOVED_EVENT, this.handleCardRemoved)
        }
    }

    private readonly handleCardAdded = (event: Event) => {
        const { card } = (event as CustomEvent<CardAddedEventDetail>).detail
        this.incrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private readonly handleCardStatusesChanged = () => {
        this.statusCounts.clear()
        const cards = this.service.getState().snapshot?.activeCards ?? []
        for (const card of cards) this.incrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private readonly handleCardRemoved = (event: Event) => {
        const { card } = (event as CustomEvent<CardRemovedEventDetail>).detail
        this.decrementStatus(statusOf(card))
        this.publishVisibleColumns()
    }

    private incrementStatus(status: string) {
        this.statusCounts.set(status, (this.statusCounts.get(status) ?? 0) + 1)
    }

    private decrementStatus(status: string) {
        const nextCount = (this.statusCounts.get(status) ?? 0) - 1
        if (nextCount > 0) {
            this.statusCounts.set(status, nextCount)
        } else {
            this.statusCounts.delete(status)
        }
    }

    private publishVisibleColumns() {
        const nextColumns = this.visibleColumns()
        if (areSameColumns(this.columns, nextColumns)) return

        this.columns = nextColumns
        this.listener?.()
    }

    private visibleColumns() {
        return this.states
            .map(({ alwaysVisible, color, state }, index) => ({
                alwaysVisible,
                color: color ?? defaultColumnAccent(index),
                status: state,
            }))
            .filter(({ alwaysVisible, status }) => alwaysVisible || this.statusCounts.has(status))
            .map(({ color, status }) => ({ color, status }))
    }
}

/** Subscribes only to changes in which configured board columns must be visible. */
export function useCardViewColumns(states: StateConfig[], service: DataService = dataService) {
    const store = useMemo(() => new CardViewColumnStore(states, service), [service, states])

    return useSyncExternalStore(store.subscribe, store.getSnapshot, store.getSnapshot)
}

import { DEFAULT_STATES, defaultColumnAccent, type Card, type StateConfig } from './data_types'

/** A status column with its cards already ordered by the `after` chain. */
export interface CardColumn {
    cards: Card[]
    status: string
}

/** Board column with its resolved configured accent. */
export interface BoardColumn extends CardColumn {
    color: string
}

/** A minimal header change produced by a drag: the fields a move rewrites. */
export interface CardMoveUpdate {
    after: string | null
    path: string
    status: string
}

/** Cards with a null/empty status share this column key so grouping stays total. */
export const UNASSIGNED_STATUS = ''

/** A card's column key, mapping a missing status onto the unassigned column. */
export function statusOf(card: Card) {
    return card.header.status ?? UNASSIGNED_STATUS
}

/**
 * Order a single column's cards by the `after` chain, where a card's `after`
 * holds the `internalId` of the card that precedes it. Cards whose `after` is
 * empty or points outside the set are treated as heads (kept in input order),
 * and any cards left over by cycles or duplicate links are appended stably.
 */
export function orderByAfter(cards: Card[]): Card[] {
    const byInternalId = new Map<string, Card>()
    for (const card of cards) {
        if (card.header.internalId) byInternalId.set(card.header.internalId, card)
    }

    const followerOf = new Map<string, Card>()
    const heads: Card[] = []
    for (const card of cards) {
        const after = card.header.after
        if (after && byInternalId.has(after) && !followerOf.has(after)) {
            followerOf.set(after, card)
        } else {
            heads.push(card)
        }
    }

    const ordered: Card[] = []
    const visited = new Set<Card>()
    for (const head of heads) {
        let current: Card | undefined = head
        while (current && !visited.has(current)) {
            ordered.push(current)
            visited.add(current)
            current = current.header.internalId ? followerOf.get(current.header.internalId) : undefined
        }
    }
    for (const card of cards) {
        if (!visited.has(card)) ordered.push(card)
    }

    return ordered
}

/** Group cards into columns by distinct status, preserving first-seen order. */
export function groupByStatus(cards: Card[]): CardColumn[] {
    const order: string[] = []
    const buckets = new Map<string, Card[]>()

    for (const card of cards) {
        const status = statusOf(card)
        const bucket = buckets.get(status)
        if (bucket) {
            bucket.push(card)
        } else {
            buckets.set(status, [card])
            order.push(status)
        }
    }

    return order.map((status) => ({ cards: orderByAfter(buckets.get(status) ?? []), status }))
}

/** Build board columns in configured state order, omitting empty states unless they are always visible. */
export function buildCardColumns(cards: Card[], states: StateConfig[]): BoardColumn[] {
    return states
        .map(({ color, state }, index) => ({
            cards: orderByAfter(cards.filter((card) => statusOf(card) === state)),
            color: color ?? defaultColumnAccent(index),
            status: state,
        }))
        .filter((column, index) => states[index].alwaysVisible || column.cards.length > 0)
}

/** Derive state definitions from the distinct non-empty card states in first-seen order. */
export function deriveStatesFromCards(cards: Card[]): StateConfig[] {
    const states = cards
        .map((card) => statusOf(card))
        .filter((state, index, values) => state.length > 0 && values.indexOf(state) === index)

    return states.map((state, index) => ({ alwaysVisible: false, color: defaultColumnAccent(index), state }))
}

/** Keep discovered state order and append missing default state definitions. */
export function mergeStatesWithDefaults(states: StateConfig[]): StateConfig[] {
    const defaultsByState = new Map(DEFAULT_STATES.map((stateConfig) => [stateConfig.state, stateConfig]))
    const mergedStates = states.map((stateConfig, index) => defaultsByState.get(stateConfig.state) ?? {
        ...stateConfig,
        color: stateConfig.color ?? defaultColumnAccent(index),
    })
    const mergedStateNames = new Set(mergedStates.map(({ state }) => state))

    return [...mergedStates, ...DEFAULT_STATES.filter(({ state }) => !mergedStateNames.has(state))]
}

function clamp(value: number, min: number, max: number) {
    return Math.min(Math.max(value, min), max)
}

function addColumnOrderingUpdates(
    orderedCards: Card[],
    status: string,
    updates: Map<string, CardMoveUpdate>,
) {
    for (let index = 0; index < orderedCards.length; index += 1) {
        const card = orderedCards[index]
        const predecessor = orderedCards[index - 1]
        const predecessorInternalId = predecessor?.header.internalId ?? null
        if (predecessor && !predecessorInternalId) {
            throw new Error(`Cannot order card after a card without an internalId: ${predecessor.path}`)
        }

        updates.set(card.path, { after: predecessorInternalId, path: card.path, status })
    }
}

/**
 * Compute header changes to move `cardPath` into `targetStatus` at
 * `targetIndex`. Both affected columns are rebuilt as single valid chains, then
 * unchanged links are filtered out. A valid input chain still changes at most
 * the moved card, its new follower, and its old follower.
 */
export function computeMove(
    cards: Card[],
    cardPath: string,
    targetStatus: string,
    targetIndex: number,
): CardMoveUpdate[] {
    const moved = cards.find((card) => card.path === cardPath)
    if (!moved) return []

    const updates = new Map<string, CardMoveUpdate>()
    const sourceStatus = statusOf(moved)
    const sourceOrdered = orderByAfter(cards.filter((card) => statusOf(card) === sourceStatus))
    const sourceWithoutMoved = sourceOrdered.filter((card) => card.path !== cardPath)
    const targetOrdered = sourceStatus === targetStatus
        ? sourceWithoutMoved
        : orderByAfter(cards.filter((card) => statusOf(card) === targetStatus))
    const insertIndex = clamp(targetIndex, 0, targetOrdered.length)
    const nextTargetOrder = [...targetOrdered]
    nextTargetOrder.splice(insertIndex, 0, moved)

    addColumnOrderingUpdates(nextTargetOrder, targetStatus, updates)
    if (sourceStatus !== targetStatus) addColumnOrderingUpdates(sourceWithoutMoved, sourceStatus, updates)

    const byPath = new Map(cards.map((card) => [card.path, card]))

    return [...updates.values()].filter((update) => {
        const card = byPath.get(update.path)
        if (!card) return true

        return card.header.after !== update.after || statusOf(card) !== update.status
    })
}

